Here's a C++ program that uses a recursive function to generate the Fibonacci sequence, starting with two given integers as the first two sequence elements:

```cpp
#include <iostream>
#include <string>
#include <stdexcept>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 0) {
        return a;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int first, second, numElements;

    cout << "Enter the first two integers: ";
    getline(cin, input);

    istringstream iss(input);
    iss >> first >> second;

    if (iss.fail() || first < 0 || second < 0) {
        throw runtime_error("Invalid input");
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> numElements;

    if (numElements <= 0) {
        throw runtime_error("Invalid input");
    }

    int sequence[numElements];
    sequence[0] = first;
    sequence[1] = second;

    for (int i = 2; i < numElements; i++) {
        sequence[i] = fibonacci(i, first, second);
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < numElements; i++) {
        cout << sequence[i] << ", ";
    }
    cout << endl;

    return 0;
}
```

To solve this problem, I'll use a combination of string manipulation and regular expressions in Swift. Here's a function that takes in the passage as input and returns the corrected passage with all homophones corrected:

```swift
func correctHomophones(in passage: String) -> String {
    let regex = try! NSRegularExpression(pattern: "\\b(there|their|they're)\\b", options: [])
    let range = NSRange(location: 0, length: passage.utf16.count)
    let matches = regex.matches(in: passage, options: [], range: range)

    for match in matches {
        let originalText = (passage as NSString).substring(with: match.range)
        let correctedText = originalText.replacingOccurrences(of: "there", with: "there")
                                .replacingOccurrences(of: "their", with: "their")
                                .replacingOccurrences(of: "they're", with: "they're")
        passage = (passage as NSString).replacingCharacters(in: match.range, with: correctedText)
    }

    return passage
}
```

