```go
package main

import (
	"fmt"
	"os"
	"reflect"

	"github.com/apache/avro/v2/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ./parse_go_struct <go_source_file> <struct_name>")
		os.Exit(1)
	}

	goSourceFile := os.Args[1]
	structName := os.Args[2]

	typeInfo, err := reflect.TypeOfAndValue(nil, structName).Type()
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	schemaDef, err := generateAvroSchema(typeInfo)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	outputFile, err := os.OpenFile("struct.avsc", os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
	defer outputFile.Close()

	enc := schema.NewEncoder(outputFile)
	err = enc.WriteSchema(schemaDef)
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

