function createNewArray(inputArray) {
  const resultsArray = [];

  for (let i = 0; i < inputArray.length; i++) {
    const item = inputArray[i];
    const randomize = item.randomize;

    if (!randomize) {
      resultsArray[item.position - 1] = item;
    } else {
      const randomIndex = Math.floor(Math.random() * (inputArray.length - 1)) + 1;
      resultsArray[randomIndex] = item;
    }
  }

  return resultsArray;
}

