#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    char *cstring = NULL;

    // Allocate memory for the C string
    cstring = malloc(sizeof(char) * (strlen(argv[0]) + 1));

    // Copy the first argument to the C string
    strcpy(cstring, argv[0]);

    // Print the C string
