To create a simple toast notification using React Context, follow these steps:

1. First, create a `ToastContext` file to define the context and its provider:

```javascript
// src/contexts/ToastContext.js
import { createContext, useReducer } from 'react';

const initialState = {
  showToast: false,
  message: '',
};

function reducer(state, action) {
  switch (action.type) {
    case 'SHOW_TOAST':
      return { ...state, showToast: true, message: action.message };
    case 'HIDE_TOAST':
      return { ...state, showToast: false, message: '' };
    default:
      return state;
  }
}

export const ToastContext = createContext();

export function ToastProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  function showToast(message) {
    dispatch({ type: 'SHOW_TOAST', message });
  }

  function hideToast() {
    dispatch({ type: 'HIDE_TOAST' });
  }

  return (
    <ToastContext.Provider value={{ showToast, hideToast, state }}>
      {children}
    </ToastContext.Provider>
  );
}
```

2. Next, create a `Toast` component to display the toast notification:

```javascript
// src/components/Toast.js
import React from 'react';
import { ToastContext } from '../contexts/ToastContext';

function Toast() {
  const { showToast, message } = React.useContext(ToastContext);

  if (!showToast) {
    return null;
  }

  return (
    <div className="toast">
      <p>{message}</p>
    </div>
  );
}

export default Toast;
```

