Here's a sample C++ program representing a book with member variables for the title, author, and summary:

```cpp
#include <iostream>
#include <string>
using namespace std;

class Book {
public:
    string title;
    string author;
    string summary;

    void setTitle(string t) {
        title = t;
    }

    void setAuthor(string a) {
        author = a;
    }

    void setSummary(string s) {
        summary = s;
    }

    string getTitle() const {
        return title;
    }

    string getAuthor() const {
        return author;
    }

    string getSummary() const {
        return summary;
    }

    bool compare(const Book& other) const {
        return (title == other.title && author == other.author && summary == other.summary);
    }
};

int main() {
    Book catcher("The Catcher in the Rye", "J.D. Salinger", "A young boy struggles with growing up and conformity.");
    Book book1("To Kill a Mockingbird", "Harper Lee", "A young girl learns about racism and injustice in the American South.");
    Book book2("1984", "George Orwell", "A dystopian novel where a totalitarian government controls every aspect of citizens' lives.");

    // Check if any two books have the same title, author, and summary
    if (catcher.compare(book1)) {
        cout << "Books have the same title, author, and summary." << endl;
    } else if (catcher.compare(book2)) {
        cout << "Books have the same title, author, and summary." << endl;
    } else {
        cout << "No two books have the same title, author, and summary." << endl;
    }

    return 0;
}
```

