const { Redis } = require('ioredis');

class RedisClient {
  constructor() {
    this.redis = new Redis({
      host: 'localhost',
      port: 6379,
      family: 4, // Use IPv4
    });

    this.redis.on('error', (error) => {
      console.error('Redis error:', error);
    });
  }

  async isAlive() {
    try {
      await this.redis.ping();
      return true;
    } catch (error) {
      return false;
    }
  }

  async get(key) {
    const value = await this.redis.get(key);
    return value;
  }

  async set(key, value, duration) {
    await this.redis.setex(key, duration, value);
  }

  async del(key) {
    await this.redis.del(key);
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This code defines a `RedisClient` class with methods for connecting to Redis, checking if the connection is alive, getting and setting values, and deleting keys. It also exports an instance of the `RedisClient` class called `redisClient`.

